package br.com.pacto.recrutamento.infra.templatevaga; import br.com.pacto.recrutamento.app.templatevaga.TemplateVagaRepositorio; import br.com.pacto.recrutamento.core.entities.TemplateVaga; import org.springframework.stereotype.Repository; import java.util.*; @Repository class TemplateVagaJpaAdapter implements TemplateVagaRepositorio {private final TemplateVagaJpaRepository r;private final TemplateVagaJpaMapper m;TemplateVagaJpaAdapter(TemplateVagaJpaRepository r,TemplateVagaJpaMapper m){this.r=r;this.m=m;}public Optional<TemplateVaga> buscarAtivoPorId(UUID id){return id==null?Optional.empty():r.findByIdAndExcluidoEmIsNull(id).map(m::paraDominio);}public TemplateVaga salvar(TemplateVaga x){return m.paraDominio(r.save(m.paraEntidade(x)));}}
